/*
 * Generated by speexdsp's configure from speexdsp_config_types.h.in.
 *
 * Written out here instead, because this copy of speexdsp is compiled into
 * the toolkit rather than built with autotools. Every target Schultz builds
 * for has <stdint.h>, so the fixed width types are the ones C99 already
 * names and there is nothing to detect.
 */
#ifndef __SPEEX_TYPES_H__
#define __SPEEX_TYPES_H__

#include <stdint.h>

typedef int16_t spx_int16_t;
typedef uint16_t spx_uint16_t;
typedef int32_t spx_int32_t;
typedef uint32_t spx_uint32_t;

#endif
